-- One-time repricing of the 18 demo works to between US$3,000 and US$8,000, keeping the demo
-- catalogue under the US$10,000 price cap. Only demo works in the three demo galleries are touched;
-- existing orders keep the price they were placed at.
UPDATE `listings` SET `price_cents` = 390000 WHERE `slug` = 'threshold-of-ember-camille-vasseur' AND `gallery_id` IN (SELECT `id` FROM `galleries` WHERE `slug` IN ('atelier-lumiere', 'noir-gallery', 'form-and-void-studio'));--> statement-breakpoint
